import{_ as e,c as o,o as a,ag as l}from"./chunks/framework._xRlcm3f.js";const r="/siyuan-plugin-publisher/images/shots/typecho-latex-config.webp",i="/siyuan-plugin-publisher/images/shots/typecho-latex-result.webp",b=JSON.parse('{"title":"Typecho 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/metaweblog-typecho.md","filePath":"platforms/metaweblog-typecho.md","lastUpdated":1790228279000}'),s={name:"platforms/metaweblog-typecho.md"};function d(n,t,p,c,h,g){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="typecho-配置指南" tabindex="-1">Typecho 配置指南 <a class="header-anchor" href="#typecho-配置指南" aria-label="Permalink to &quot;Typecho 配置指南&quot;">​</a></h1><p>通过 <strong>MetaWeblog XML-RPC</strong> 协议把思源笔记发布到自建的 <strong>Typecho</strong> 博客。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可访问的 <strong>Typecho</strong> 站点，并开启 MetaWeblog 接口（Typecho 默认提供 XML-RPC 端点）。</li><li>Typecho 后台的<strong>登录用户名与登录密码</strong>（MetaWeblog 按账号密码鉴权，不使用 Token）。</li><li>站点可被公网或本机访问；若使用代理请在插件设置中配置跨域代理。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>博客首页</td><td>你的 Typecho 博客首页地址，如 <code>https://blog.example.com</code></td></tr><tr><td>API 地址</td><td>MetaWeblog API 地址，默认由博客首页推导（Typecho 通常为首页下的 <code>/action/xmlrpc</code>），核对无误后一般无需修改</td></tr><tr><td>用户名</td><td>Typecho 后台的登录用户名</td></tr><tr><td>密码</td><td>Typecho 后台的登录密码</td></tr><tr><td>查看文章链接</td><td>查看链接模板，默认 <code>/index.php/archives/[postid]</code>，与 Typecho 的文章地址一致</td></tr><tr><td>发布格式</td><td>正文提交格式，默认 HTML，保持默认即可</td></tr><tr><td>图床</td><td>按需选择「当前平台」「PicGo 强烈推荐」或「不使用」</td></tr></tbody></table><blockquote><p>Typecho 通过 MetaWeblog 发布时不暴露分类目录选择，因此配置页<strong>没有「发布目录」行</strong>。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 站点连通性与账号校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 Typecho → 发布。文章提交到站点。</li><li>「查看文章」按 <code>/index.php/archives/[postid]</code> 打开；若站点启用了伪静态，请在「查看规则」里改成实际形态。</li></ol><h2 id="四、公式支持" tabindex="-1">四、公式支持 <a class="header-anchor" href="#四、公式支持" aria-label="Permalink to &quot;四、公式支持&quot;">​</a></h2><p>Typecho 默认不渲染 LaTeX 公式。安装 <strong>KaTeX 渲染插件</strong>并按其说明配置标识符即可。</p><ol><li><p>安装 <a href="https://github.com/dreamerblue/AutoLaTeX" target="_blank" rel="noreferrer">KaTeX4Typecho</a> 插件并启用。</p></li><li><p>在插件设置里把「公式标识符」改成：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{left: &quot;$$&quot;, right: &quot;$$&quot;, display: true},{left: &quot;$&quot;, right: &quot;$&quot;, display: false}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+r+'" alt="填写公式标识符" loading="lazy"></p></li><li><p>保存后刷新页面，公式即可正常渲染。</p><p><img src="'+i+'" alt="公式渲染效果" loading="lazy"></p></li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证失败或提示账号错误</strong>：确认用户名是后台登录用户名、密码是登录密码（不使用 Token）；再确认 API 地址确实是站点的 XML-RPC 端点。</li><li><strong>为什么没有「发布目录」</strong>：该协议发布时不暴露分类目录选择，文章直接进入站点。</li><li><strong>图片要怎么发布</strong>：按需选择图床。「当前平台」随文章提交到站点；「PicGo 强烈推荐」先在上层设置里配置好 PicGo；「不使用」则按原图地址引用。</li><li><strong>更新与删除</strong>：点「更新」会覆盖站点上的同一篇文章；「删除」会移除该文章。</li></ul>',14)])])}const m=e(s,[["render",d]]);export{b as __pageData,m as default};
